-- c005-v001: ہر –کا ایمان–رکھنے–والا کہ یسوع ہے –کا مسیح، –سے –کے خدا پیدا–ہوا–ہے، اور ہر –کا محبت–کرنے–والا –کو جنم–دینے–والے، محبت–کرتا–ہے بھی –سے پیدا–ہوئے –سے اُس۔
-- c005-v002: میں اِس جانتے–ہیں کہ محبت–کرتے–ہیں –کو فرزندوں –کے خدا، جب –سے خدا محبت–کریں، اور –کو احکام اُس–کے کریں۔
-- c005-v003: یہ کیونکہ ہے –کی محبت –کے خدا، تاکہ –کو احکام اُس–کے مانیں؛ اور –کے احکام اُس–کے بھاری نہیں ہیں۔
-- c005-v004: کیونکہ ہر –کا پیدا–ہوا –سے –کے خدا، فتح–پاتا–ہے –پر دنیا؛ اور یہ ہے –کی فتح –کی فتح–پانے–والی –پر دنیا --  –کی ایمان ہمارا۔
-- c005-v005: کون لیکن ہے –کا فتح–پانے–والا –پر دنیا، اگر نہیں –کا ایمان–رکھنے–والا کہ یسوع ہے –کا بیٹا –کے خدا؟
-- c005-v006: یہ ہے –کا آیا –کے–ذریعے پانی اور خون، یسوع مسیح؛ نہ میں –کے پانی صرف، بلکہ میں –کے پانی اور میں –کے خون۔ اور –کی روح ہے –کی گواہی–دینے–والی، کیونکہ –کی روح ہے –کی سچائی۔
-- c005-v007: کیونکہ تین ہیں –کے گواہی–دینے–والے {میں –کے آسمان: –کا باپ، –کا کلام، اور –کی قدوس روح-- اور یہ –کے تین، ایک ہیں};
-- c005-v008: –کی روح، اور –کا پانی، اور –کا خون-- اور –کے تینوں –میں –کے ایک ہیں۔
-- c005-v009: اگر –کی گواہی –کے انسانوں قبول–کرتے–ہیں، –کی گواہی –کے خدا بڑی ہے۔ کیونکہ یہ ہے –کی گواہی –کے خدا، کہ گواہی–دی–ہے –کے–بارے–میں –کے بیٹے اپنے۔
-- c005-v010: –کا ایمان–رکھنے–والا –پر –کے بیٹے –کے خدا، رکھتا–ہے –کی گواہی میں اپنے–آپ؛ –کا نہ ایمان–رکھنے–والا –کے خدا، جھوٹا بنایا–ہے اُسے، کیونکہ نہیں ایمان–لایا–ہے –پر –کی گواہی جو گواہی–دی–ہے –کا خدا، –کے–بارے–میں –کے بیٹے اپنے۔
-- c005-v011: اور یہ ہے –کی گواہی، کہ زندگی ابدی دیا –کا خدا، ہمیں اور یہ –کی زندگی میں –کے بیٹے اُس–کے ہے۔
-- c005-v012: –کا رکھنے–والا –کو بیٹے، رکھتا–ہے –کی زندگی: –کا نہ رکھنے–والا –کو بیٹے –کے خدا، –کی زندگی نہیں رکھتا۔
-- c005-v013: یہ لکھا تمہیں تاکہ جانو کہ زندگی رکھتے–ہو ابدی، –کے ایمان–لانے–والوں –پر –کے نام –کے بیٹے –کے خدا، <اور تاکہ ایمان–لاؤ –پر –کے نام –کے بیٹے –کے خدا>
-- c005-v014: اور یہ ہے –کی دلیری جو رکھتے–ہیں –کے–نزدیک اُس، کہ اگر کچھ مانگیں –کے–مطابق –کے مرضی اُس–کی، سنتا–ہے ہماری۔
-- c005-v015: اور اگر جانتے–ہیں کہ سنتا–ہے ہماری، جو اگر مانگیں، جانتے–ہیں کہ رکھتے–ہیں –کو درخواستیں جو مانگی–ہیں –سے اُس۔
-- c005-v016: اگر کوئی دیکھے –کو بھائی اپنے گناہ–کرتے گناہ نہ –کی–طرف موت، مانگے، اور دے–گا اُسے زندگی --  –کو گناہ–کرنے–والوں نہ –کی–طرف موت۔ ہے گناہ –کی–طرف موت؛ نہیں –کے–بارے–میں اُس کہتا–ہوں تاکہ مانگے۔
-- c005-v017: ہر ناراستی گناہ ہے؛ اور ہے گناہ نہ –کی–طرف موت۔
-- c005-v018: جانتے–ہیں کہ ہر –کا پیدا–ہوا –سے –کے خدا نہیں گناہ–کرتا، بلکہ –کا پیدا–ہوا –سے –کے خدا حفاظت–کرتا–ہے اُسے، اور –کا شریر نہیں چھوتا اُس۔
-- c005-v019: جانتے–ہیں کہ –سے –کے خدا ہیں، اور –کی دنیا ساری، میں –کے شریر پڑی–ہے۔
-- c005-v020: جانتے–ہیں لیکن کہ –کا بیٹا –کے خدا آیا–ہے، اور دیا–ہے ہمیں سمجھ، تاکہ جانیں –کو سچے؛ اور ہیں میں –کے سچے، میں –کے بیٹے اُس–کے، یسوع مسیح۔ یہ ہے –کا سچا خدا، اور زندگی ابدی۔
